package org.jsoup.helper;

import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class StringUtil {
    public static String borrowBuilder() {
        return "";
    }

    public static String encode(String value) throws UnsupportedEncodingException {
        return URLEncoder.encode(value, StandardCharsets.UTF_8.toString());
    }
}

public class Connection {

    public interface KeyVal {
        String getKey();
        String getValue();
    }

    public static class KeyValImpl implements KeyVal {
        private String key;
        private String value;

        public KeyValImpl(String key, String value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public String getKey() {
            return key;
        }

        @Override
        public String getValue() {
            return value;
        }
    }

    public static List<KeyVal> l = new ArrayList<>();

    public static void addConnection(KeyVal kv) {
        l.add(kv);
    }

    public static String decodePart(String part, String encoding) throws UnsupportedEncodingException {
        return URLEncoder.encode(part, StandardCharsets.UTF_8.toString());
    }

    public static List<String> encode(List<String> parts) throws UnsupportedEncodingException {
        List<String> result = new ArrayList<>();
        for (String part : parts) {
            result.add StringUtil.encode(part));
        }
        return result;
    }
}
